define(['core/log'], function(Log) { 'use strict'; const STORAGE_KEY = 'edzcorp_theme'; const DARK_VALUE = 'dark'; const LIGHT_VALUE = 'light'; const DATA_ATTR = 'data-edz-theme'; const applyTheme = (theme) => { const html = document.documentElement; const toggle = document.getElementById('edz-darkmode-toggle'); if (theme === DARK_VALUE) { html.setAttribute(DATA_ATTR, DARK_VALUE); } else { html.removeAttribute(DATA_ATTR); } if (toggle) { toggle.setAttribute( 'aria-pressed', String(theme === DARK_VALUE) ); } }; const saveTheme = (theme) => { try { localStorage.setItem(STORAGE_KEY, theme); } catch (e) { Log.debug('EdzCorp theme: localStorage unavailable', e); } }; const loadTheme = () => { let stored = null; try { stored = localStorage.getItem(STORAGE_KEY); } catch (e) { stored = null; } if (stored === DARK_VALUE || stored === LIGHT_VALUE) { return stored; } if (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) { return DARK_VALUE; } return LIGHT_VALUE; }; const toggleDarkMode = () => { const html = document.documentElement; const isDark = html.getAttribute(DATA_ATTR) === DARK_VALUE; const nextTheme = isDark ? LIGHT_VALUE : DARK_VALUE; applyTheme(nextTheme); saveTheme(nextTheme); }; const initSmoothScroll = () => { document.querySelectorAll('a[href^="#"]').forEach(anchor => { anchor.addEventListener('click', (e) => { const target = document.querySelector(anchor.getAttribute('href')); if (target) { e.preventDefault(); target.scrollIntoView({ behavior: 'smooth', block: 'start' }); } }); }); }; const initCardHover = () => { if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) { return; } const cards = document.querySelectorAll('.dashboard-card, .course-info-container'); cards.forEach(card => { card.addEventListener('mousemove', (e) => { const rect = card.getBoundingClientRect(); const x = e.clientX - rect.left - rect.width / 2; const y = e.clientY - rect.top - rect.height / 2; const rotX = (-y / rect.height) * 4; const rotY = ( x / rect.width) * 4; card.style.transform = `perspective(600px) rotateX(${rotX}deg) rotateY(${rotY}deg) translateY(-1px)`; }); card.addEventListener('mouseleave', () => { card.style.transform = ''; }); }); }; const init = () => { applyTheme(loadTheme()); const toggle = document.getElementById('edz-darkmode-toggle'); if (toggle) { toggle.addEventListener('click', toggleDarkMode); } if (window.matchMedia) { window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', (e) => { let stored = null; try { stored = localStorage.getItem(STORAGE_KEY); } catch (_) { } if (!stored) { applyTheme(e.matches ? DARK_VALUE : LIGHT_VALUE); } }); } initSmoothScroll(); initCardHover(); }; return { init }; });